mapper.select:
SELECT po.id, po.order_no, po.hospital_id, po.supplier, po.status, po.total_amount, po.remark, po.created_by, po.created_at, po.updated_at, h.name AS hospital_name, u.real_name AS created_by_name FROM purchase_order po LEFT JOIN hospital h ON po.hospital_id = h.id LEFT JOIN sys_user u ON po.created_by = u.id
AND po.order_no LIKE CONCAT('%', #{orderNo}, '%') AND po.hospital_id = #{hospitalId} AND po.status = #{status}
ORDER BY po.created_at DESC
